import React from 'react';

import { getAllProducts } from '@apps/Products/@services/products.service';
import { IProduct } from '@apps/Products/@types/products.types';
import PohAlert from '@ui-kit/Alert';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';

import ProductAddModal from '../ProductAddModal';

interface IProductSelectModalProps {
  excludeIds?: number[];
  onSelect: (selected: IProduct) => void;
}

const ProductSelectModal: React.FC<IProductSelectModalProps> = ({ onSelect, excludeIds }) => {
  const [data, setData] = React.useState<IProduct[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState<Error>();
  const [q, setQ] = React.useState('');
  const [addMode, setAddMode] = React.useState(false);

  React.useEffect(() => {
    async function fetch() {
      try {
        setIsLoading(true);
        const res = await getAllProducts();
        setData(res);
      } catch (e) {
        setError(e as Error);
      } finally {
        setIsLoading(false);
      }
    }
    fetch();
  }, []);

  if (isLoading) {
    return <PohLoader />;
  }

  if (error) {
    return <PohAlert>{error.message}</PohAlert>;
  }

  const filteredData = data.filter((p) => {
    if (q.length) return p.name.toLowerCase().includes(q.trim().toLocaleLowerCase());
    if (excludeIds?.length) return !excludeIds.includes(p.id);
    return true;
  });

  return (
    <div style={{ width: 400 }}>
      {!addMode && (
        <header className="mb-2 d-flex">
          <PohInput
            wrapperClassName="flex-grow-1"
            placeholder="Найти"
            value={q}
            autoFocus
            onChange={(v) => setQ(v ?? '')}
            type={InputTypes.search}
          />
          <PohButton
            className="ms-5"
            variant={filteredData.length > 0 ? ButtonVariant.Light : ButtonVariant.Success}
            onClick={() => {
              setAddMode(true);
            }}
          >
            Добавить
          </PohButton>
        </header>
      )}
      {!addMode && (
        <div style={{ overflowY: 'auto', maxHeight: 400 }}>
          <PohList
            data={filteredData.map((fa) => ({
              key: fa.id,
              action: true,
              content: fa.name,
              onClick: () => onSelect(fa),
            }))}
          />
        </div>
      )}
      {addMode && <ProductAddModal onSave={onSelect} data={{ name: q }} />}
    </div>
  );
};

export default ProductSelectModal;
